// @generated by tsrust api. Uses the host Fetch API without retries.
import { ApiError, contractId, manifest } from './index.js';

export function createHttpTransport(options) {
  const endpoint = new URL(options.url);
  if (!['http:', 'https:'].includes(endpoint.protocol) || endpoint.username || endpoint.password || endpoint.hash) {
    throw new TypeError('API endpoint must be an HTTP(S) URL without credentials or fragment');
  }
  const fetchRequest = options.fetch || globalThis.fetch?.bind(globalThis);
  if (typeof fetchRequest !== 'function') throw new TypeError('A Fetch API implementation is required');
  const allowed = new Set(manifest.operations.map(operation => operation.name));
  return Object.freeze({
    async request(operation, input, callOptions) {
      if (!allowed.has(operation)) throw new ApiError('api-operation', 'Operation is not declared in this client', operation);
      const signal = callOptions?.signal;
      const cancelled = () => new ApiError('api-cancelled', 'API request cancelled; backend completion is unknown', operation);
      if (signal?.aborted) throw cancelled();
      let response;
      let body;
      try {
        // Resolve application credentials for every call, including after a session change.
        const supplied = typeof options.headers === 'function' ? await options.headers() : options.headers;
        if (signal?.aborted) throw cancelled();
        const headers = new Headers(supplied);
        headers.set('accept', 'application/json');
        headers.set('content-type', 'application/json');
        headers.set('x-tsrust-contract', contractId);
        response = await fetchRequest(endpoint.href, {
          method: 'POST', headers, body: JSON.stringify({ operation, input }),
          signal, credentials: 'omit', redirect: 'error',
        });
        body = await response.text();
      } catch (error) {
        if (signal?.aborted) throw cancelled();
        // Do not expose request headers, URLs or host exception messages to callers.
        throw new ApiError('api-network', 'API request failed before a complete response was received', operation);
      }
      if (signal?.aborted) throw cancelled();
      const mediaType = response.headers.get('content-type')?.split(';', 1)[0].trim().toLowerCase();
      if (mediaType !== 'application/json') {
        throw new ApiError(response.ok ? 'api-protocol' : 'api-http', `API returned HTTP ${response.status} without JSON`, operation);
      }
      let value;
      try { value = JSON.parse(body); }
      catch { throw new ApiError('api-protocol', 'API returned invalid JSON', operation); }
      // Preserve structured public failures on non-2xx responses, but never accept success there.
      if (!response.ok && (value === null || typeof value !== 'object' || value.ok !== false ||
          value.error === null || typeof value.error !== 'object' ||
          typeof value.error.code !== 'string' || typeof value.error.message !== 'string')) {
        throw new ApiError('api-http', `API returned HTTP ${response.status}`, operation);
      }
      return value;
    },
  });
}
